from playwright.sync_api import sync_playwright
URL=__import__("fcenv").APP_URL
errs=[]; fails=[]
def ck(n,c,info=""):
    print(("OK   " if c else "FAIL ")+n,info)
    if not c: fails.append(n)
with sync_playwright() as p:
    b=p.chromium.launch(); c=b.new_context(viewport={"width":390,"height":844},is_mobile=True,has_touch=True); pg=c.new_page()
    pg.on("pageerror",lambda e:errs.append(str(e))); pg.on("console",lambda m: errs.append(m.text) if m.type=="error" else None)
    pg.goto(URL); pg.wait_for_timeout(600)
    # Tab erreichbar
    pg.evaluate("showTab('uebungen')"); pg.wait_for_timeout(200)
    ck("Link-Karte in Uebungen", pg.evaluate("!!document.querySelector('#panel-uebungen [data-goto=ausblick]')"))
    pg.click('#panel-uebungen [data-goto="ausblick"]'); pg.wait_for_timeout(400)
    ck("Ausblick sichtbar", pg.evaluate("!document.getElementById('panel-ausblick').hidden"))
    ck("Subnav hat Ausblick", pg.evaluate("[...document.querySelectorAll('#subnav .tab')].map(x=>x.textContent).join()")=="Übungen,Tipps,Ausblick")
    ck("Seitentitel", pg.inner_text("#pagetitle")=="Training" and "Ausrüstung" in pg.inner_text("#pagesub"), pg.inner_text("#pagesub"))
    ck("8 Ausruestungs-Karten", pg.evaluate("document.querySelectorAll('#panel-ausblick .gearcard').length")==8)
    ck("Wegplan: aktuelle Phase offen", pg.evaluate("document.querySelectorAll('#panel-ausblick .road li.cur details[open]').length")==1)
    ck("Woche 1 = Technik", "Technik lernen" in pg.evaluate("document.querySelector('#panel-ausblick .road li.cur').innerText"))
    # Links
    hrefs=pg.evaluate("[...document.querySelectorAll('#panel-ausblick .gearcard[data-gearcard=matte] a')].map(a=>a.href+'|'+a.target+'|'+a.rel)")
    ck("3 Links Matte", len(hrefs)==3, hrefs)
    ck("Amazon-Link", hrefs[0].startswith("https://www.amazon.de/s?k=Gymnastikmatte%2010%20mm%20rutschfest"), hrefs[0])
    ck("Otto-Link", hrefs[1].startswith("https://www.otto.de/suche/Gymnastikmatte%2010%20mm%20rutschfest/"), hrefs[1])
    ck("Kleinanzeigen-Link", hrefs[2].startswith("https://www.kleinanzeigen.de/s-gymnastikmatte/k0"), hrefs[2])
    ck("Links oeffnen neu + noopener", all("_blank" in h and "noopener" in h for h in hrefs))
    ck("alle Karten mit Links ausser Tuerreck", pg.evaluate("[...document.querySelectorAll('#panel-ausblick .gearcard')].every(c=>c.classList.contains('never') ? c.querySelectorAll('a').length===0 : c.querySelectorAll('a[href^=https]').length===3)"))
    ck("Tuerreck: nicht empfohlen, Zarge", "Zarge" in pg.evaluate("document.querySelector('#panel-ausblick .gearcard.never').innerText") and "Nicht bei dir" in pg.evaluate("document.querySelector('#panel-ausblick .gearcard.never').innerText"))
    # Status
    ck("Matte: jetzt sinnvoll", pg.evaluate("gearState(GEAR.find(g=>g.id==='matte')).k")=="now")
    ck("Turm: spaeter bei Neustart", pg.evaluate("gearState(GEAR.find(g=>g.id==='klimmzugturm')).k")=="later")
    ck("Hinweis naechster Schritt", "Trainingsmatte" in pg.inner_text("#panel-ausblick .road").split("Dein Weg")[0] or "Trainingsmatte" in pg.inner_text("#panel-ausblick .card"))
    ck("Summen sichtbar", "205 bis 400" in pg.inner_text("#panel-ausblick") and "60 bis 120" in pg.inner_text("#panel-ausblick"))
    # Ohne Gear: gesperrte Varianten nicht waehlbar
    pg.evaluate("openSwap('pike')"); pg.wait_for_timeout(300)
    ck("Pike: ohne Hanteln keine Kurzhantel-Option", pg.evaluate("!document.querySelector('#dlg-swap [data-swap=pikedb]')"))
    ck("Pike: gesperrte Option sichtbar", "Schulterdrücken mit Kurzhanteln" in pg.inner_text("#dlg-swap") and "Verstellbare Kurzhanteln" in pg.inner_text("#dlg-swap"))
    ck("gesperrte Option hat keinen Auswaehlen-Button", pg.evaluate("document.querySelectorAll('#dlg-swap .swopt.locked button').length")==0)
    pg.click('#dlg-swap [data-goto="ausblick"]'); pg.wait_for_timeout(400)
    ck("Dialog schliesst und Ausblick offen", pg.evaluate("!document.getElementById('dlg-swap').open && CUR==='ausblick'"))
    # Habe ich
    pg.click('#panel-ausblick [data-gear="hanteln"]'); pg.wait_for_timeout(300)
    ck("settings.gear.hanteln", pg.evaluate("settings.gear.hanteln===true"), pg.evaluate("JSON.stringify(settings.gear)"))
    ck("persistiert", pg.evaluate("JSON.parse(localStorage.getItem('fc_settings')).gear.hanteln===true"))
    ck("Karte zeigt Hast du", pg.evaluate("document.querySelector('[data-gearcard=hanteln] .gchip').textContent")=="Hast du")
    ck("Links bei Besitz ausgeblendet", pg.evaluate("document.querySelectorAll('[data-gearcard=hanteln] a').length")==0)
    ck("Toggle aria-pressed", pg.evaluate("document.querySelector('[data-gear=hanteln]').getAttribute('aria-pressed')")=="true")
    pg.evaluate("openSwap('pike')"); pg.wait_for_timeout(300)
    ck("Pike: Kurzhantel jetzt waehlbar", pg.evaluate("!!document.querySelector('#dlg-swap [data-swap=pikedb][data-mode=perm]')"))
    ck("Kurzhantel ohne 3D-Knopf", pg.evaluate("!document.querySelector('#dlg-swap [data-v3=pikedb]')"))
    ck("keine gesperrte Kurzhantel-Option mehr", "Braucht Verstellbare Kurzhanteln" not in pg.inner_text("#dlg-swap"))
    pg.click('#dlg-swap [data-swap="pikedb"][data-mode="perm"]'); pg.wait_for_timeout(300)
    ck("pikedb aktiv", pg.evaluate("EX.find(e=>e.slot==='pike').id")=="pikedb")
    pg.evaluate("document.getElementById('dlg-swap').close()")
    pg.evaluate("showTab('uebungen')"); pg.wait_for_timeout(300)
    ck("Uebungen zeigt Kurzhantel-Schulterdruecken", "Schulterdrücken mit Kurzhanteln" in pg.inner_text("#panel-uebungen"))
    ck("keine 3D-Buttons fuer pikedb", pg.evaluate("!document.querySelector('#panel-uebungen [data-v3=pikedb]')"))
    # Training mit pikedb
    r=pg.evaluate("""()=>{ settings.sets=1; startWorkout(); beginWork(); const ids=[]; for(let i=0;i<40 && W.phase!=='done';i++){ if(W.phase==='work'&&EX[W.ex].type!=='hold') setDone(9); else act('done'); if(W.phase==='rest'||W.phase==='prep') act('skip'); } return JSON.stringify(WK.length? WK[WK.length-1].sets.map(s=>s.ex):[]); }""")
    ck("Log mit pikedb", "pikedb" in r, r)
    ck("Volumen Schultern zaehlt", pg.evaluate("weekSets(weekStartISO(todayISO())).shoulder")>0)
    pg.evaluate("if(isActive()) { try{ act('stop') }catch(e){} }; document.getElementById('dlg-sum').open && document.getElementById('dlg-sum').close()")
    # Ausschalten waehrend kein Training: faellt zurueck
    pg.evaluate("showTab('ausblick')"); pg.wait_for_timeout(300)
    pg.click('#panel-ausblick [data-gear="hanteln"]'); pg.wait_for_timeout(300)
    ck("Gear aus", pg.evaluate("!settings.gear.hanteln"))
    ck("Pike faellt zurueck auf Basis", pg.evaluate("EX.find(e=>e.slot==='pike').id")=="pike", pg.evaluate("EX.find(e=>e.slot==='pike').id"))
    ck("alt bleibt gespeichert", pg.evaluate("settings.alt.pike")=="pikedb")
    pg.click('#panel-ausblick [data-gear="hanteln"]'); pg.wait_for_timeout(300)
    ck("Wieder an: pikedb zurueck", pg.evaluate("EX.find(e=>e.slot==='pike').id")=="pikedb")
    # Status mit Daten
    pg.evaluate("""()=>{ log.push({date:'2026-10-01',pushups:12,plank:65}); store.set('fc_log',log); const d=new Date(); for(let i=0;i<60;i++){ const t=new Date(d.getTime()-i*86400000*1.4).toISOString().slice(0,10); if(!sessions.includes(t)) sessions.push(t);} store.set('fc_sessions',sessions); levels.push=5; store.set('fc_levels',levels); showTab('ausblick'); }""")
    pg.wait_for_timeout(300)
    ck("Woche > 8", pg.evaluate("weekNo()")>8, pg.evaluate("weekNo()"))
    ck("Parallettes: bereit (3/3 -> now)", pg.evaluate("gearState(GEAR.find(g=>g.id==='parallettes')).k")=="now", pg.evaluate("JSON.stringify(gearState(GEAR.find(g=>g.id==='parallettes')))"))
    ck("Turm: bald (Rudern fehlt)", pg.evaluate("gearState(GEAR.find(g=>g.id==='klimmzugturm')).k")=="soon", pg.evaluate("JSON.stringify(gearState(GEAR.find(g=>g.id==='klimmzugturm')))"))
    ck("Phase Ausbauen aktiv", "Ausbauen" in pg.evaluate("document.querySelector('#panel-ausblick .road li.cur').innerText"))
    ck("Meilenstein auto: 10 Liegestuetze", pg.evaluate("MILES.find(m=>m.id==='mpush10').auto()"))
    ck("Meilenstein auto: Plank 60", pg.evaluate("MILES.find(m=>m.id==='mplank60').auto()"))
    ck("Meilenstein auto: 20 Liegestuetze noch nicht", not pg.evaluate("MILES.find(m=>m.id==='mpush20').auto()"))
    # Meilenstein manuell
    pg.evaluate("document.querySelectorAll('#panel-ausblick details.acc').forEach(d=>d.open=true)")
    pg.click('#panel-ausblick [data-ms="mpull"]'); pg.wait_for_timeout(300)
    ck("mpull gespeichert", pg.evaluate("/^\\d{4}-\\d{2}-\\d{2}$/.test(settings.ms.mpull)"))
    ck("Meilenstein bleibt offen nach Toggle (Akkordeon)", pg.evaluate("[...document.querySelectorAll('#panel-ausblick details.acc')].some(d=>d.open)"))
    ck("Button zeigt Geschafft am", "Geschafft am" in pg.inner_text('#panel-ausblick [data-ms="mpull"]'), pg.inner_text('#panel-ausblick [data-ms="mpull"]'))
    pg.click('#panel-ausblick [data-ms="mpull"]'); pg.wait_for_timeout(200)
    ck("mpull wieder aus", pg.evaluate("!settings.ms.mpull"))
    ck("auto-Meilenstein hat keinen Button", pg.evaluate("!document.querySelector('[data-ms=mpush10]')"))
    # Zukunftsuebungen
    ck("10 Zukunftsuebungen", pg.evaluate("EXFUT.length")==10 and pg.evaluate("document.querySelectorAll('#panel-ausblick .swopt.fut').length")==10)
    ck("Alle Zukunftsuebungen: gear-Ids gueltig", pg.evaluate("EXFUT.every(e=>e.gear.length && e.gear.every(g=>GEAR.some(x=>x.id===g && !x.never)))"))
    ck("Alle Zukunftsuebungen: MAPX", pg.evaluate("EXFUT.every(e=>MAPX[e.id])"))
    ck("Alle Zukunftsuebungen: Pflichtfelder", pg.evaluate("EXFUT.every(e=>e.name&&e.cue&&e.mistakes&&e.need&&e.why&&e.ladder.length===3||e.id==='rowpull'&&e.ladder.length===4)"))
    ck("3D-Alias rowband/rowpull", pg.evaluate("V3A.rowband.length===3 && V3A.rowpull.length===4 && EXFUT.filter(e=>V3A[e.id]).every(e=>V3A[e.id].length===e.ladder.length)"))
    ck("Slot-Verteilung", pg.evaluate("['squat','push','row','pike','bridge','plank'].every(s=>EXFUT.some(e=>e.slot===s))"))
    ck("Gesperrte Zukunftsuebungen ohne Button", pg.evaluate("[...document.querySelectorAll('#panel-ausblick .swopt.fut')].filter(d=>/Braucht/.test(d.innerText)).every(d=>!d.querySelector('button'))"))
    # rowband mit Baendern
    pg.click('#panel-ausblick [data-gear="baender"]'); pg.wait_for_timeout(300)
    pg.evaluate("openSwap('row')"); pg.wait_for_timeout(300)
    ck("Rudern: Band-Option da", pg.evaluate("!!document.querySelector('#dlg-swap [data-swap=rowband]')"))
    ck("Rudern: Band hat 3D", pg.evaluate("!!document.querySelector('#dlg-swap [data-v3=rowband]')"))
    pg.evaluate("document.getElementById('dlg-swap').close()")
    pg.evaluate("openV3('rowband',1)"); pg.wait_for_timeout(600)
    ck("3D rowband oeffnet", pg.evaluate("document.getElementById('dlg-3d').open") and "Rudern mit Band" in pg.inner_text("#v3-title"), pg.inner_text("#v3-title"))
    ck("3D-Alternativen ohne Ex ohne Animation", pg.evaluate("[...document.querySelectorAll('#v3-alts [data-v3alt]')].every(b=>V3A[b.dataset.v3alt])"))
    pg.evaluate("document.getElementById('dlg-3d').close()")
    # Kaputte Daten
    pg.evaluate("localStorage.setItem('fc_settings', JSON.stringify({gear:{bogus:true,matte:'ja',tuerreck:true,hanteln:true},ms:{mpull:'kaputt',mneg:'2026-10-05',mpush10:'2026-10-05',x:'2026-01-01'},alt:{pike:'pikedb',row:'rowband'}}))")
    pg.reload(); pg.wait_for_timeout(600)
    ck("gear bereinigt", pg.evaluate("JSON.stringify(settings.gear)")=='{"hanteln":true}', pg.evaluate("JSON.stringify(settings.gear)"))
    ck("ms bereinigt", pg.evaluate("JSON.stringify(settings.ms)")=='{"mneg":"2026-10-05"}', pg.evaluate("JSON.stringify(settings.ms)"))
    ck("alt: pikedb ok, rowband ohne Baender ignoriert", pg.evaluate("EX.find(e=>e.slot==='pike').id")=="pikedb" and pg.evaluate("EX.find(e=>e.slot==='row').id")=="row", pg.evaluate("EX.find(e=>e.slot==='row').id"))
    pg.evaluate("localStorage.setItem('fc_settings', JSON.stringify({gear:'x',ms:[1,2]}))")
    pg.reload(); pg.wait_for_timeout(600)
    ck("gear/ms falscher Typ -> {}", pg.evaluate("JSON.stringify([settings.gear,settings.ms])")=='[{},{}]')
    # Layout
    pg.evaluate("showTab('ausblick')"); pg.wait_for_timeout(300)
    ck("kein horizontaler Ueberlauf 390px", pg.evaluate("document.documentElement.scrollWidth")<=390, pg.evaluate("document.documentElement.scrollWidth"))
    ck("Tap-Ziele >=36px", pg.evaluate("[...document.querySelectorAll('#panel-ausblick button, #panel-ausblick a.btn, #panel-ausblick summary')].filter(e=>e.offsetParent).every(e=>e.getBoundingClientRect().height>=36)"), pg.evaluate("[...document.querySelectorAll('#panel-ausblick button, #panel-ausblick a.btn, #panel-ausblick summary')].filter(e=>e.offsetParent && e.getBoundingClientRect().height<36).map(e=>e.tagName+'.'+e.className+':'+Math.round(e.getBoundingClientRect().height)+':'+e.textContent.slice(0,20)).join()"))
    # Dunkel
    c2=b.new_context(viewport={"width":1200,"height":900},color_scheme="dark"); pg2=c2.new_page()
    pg2.on("pageerror",lambda e:errs.append(str(e)))
    pg2.goto(URL); pg2.wait_for_timeout(500); pg2.evaluate("showTab('ausblick')"); pg2.wait_for_timeout(300)
    ck("Desktop dunkel rendert", pg2.evaluate("document.querySelectorAll('#panel-ausblick .gearcard').length")==8)
    pg2.screenshot(path=__import__("fcenv").SHOTS + "/dark.png",full_page=True)
    ck("keine JS-Fehler", not errs, errs[:3])
    b.close()
print("\nFAILS:",fails)
